-- Private application tables: prevent Supabase Data API exposure.
-- Guard optional roles so the same baseline works on ordinary PostgreSQL.
DO $private_application_tables$
DECLARE
  application_table text;
  application_sequence text;
  api_role text;
BEGIN
  FOREACH application_table IN ARRAY ARRAY['Session', 'RetailerWorkspace', 'RetailerSettings', 'ImportedProductPush', 'CatalogKnowledgeProduct', 'CatalogSyncRun', 'KnowledgeDocument', 'RetailerProductRelease', 'RetailerOrder', 'SupportCase', 'BackgroundJob', 'RuntimeSourceState', '_prisma_migrations']
